<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{{ config('app.name', 'Aprende Guate') }}</title>
    <style>
        :root{color-scheme:light;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#0f172a;background:#f8fafc}*{box-sizing:border-box}body{margin:0;min-width:320px}a{color:inherit;text-decoration:none}.topbar{height:72px;display:flex;align-items:center;justify-content:space-between;gap:24px;padding:0 clamp(20px,4vw,72px);background:rgba(255,255,255,.96);border-bottom:1px solid #e2e8f0}.brand{display:inline-flex;align-items:center;gap:12px;font-weight:800;color:#172554;font-size:18px}.brand-mark{width:40px;height:40px;display:grid;place-items:center;background:#1d4ed8;border-radius:12px;color:#fff;box-shadow:0 10px 20px rgba(29,78,216,.2)}.top-actions{display:flex;align-items:center;gap:12px;font-size:14px;font-weight:700;color:#1e40af}.button{padding:11px 17px;border-radius:11px;border:1px solid #bfdbfe}.button-primary{color:#fff;background:#1d4ed8;border-color:#1d4ed8;box-shadow:0 8px 16px rgba(29,78,216,.16)}main{width:min(100% - 32px,1500px);margin:0 auto;padding:clamp(32px,5vw,80px) 0}.hero{overflow:hidden;position:relative;padding:clamp(36px,7vw,108px);border-radius:28px;color:#fff;background:linear-gradient(135deg,#172554 0%,#1d4ed8 58%,#2563eb 100%);box-shadow:0 20px 45px rgba(30,64,175,.22)}.hero:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 87% 18%,rgba(125,211,252,.48),transparent 24%),radial-gradient(circle at 72% 90%,rgba(147,197,253,.28),transparent 22%)}.hero-content{position:relative;max-width:850px}.eyebrow{display:inline-flex;align-items:center;gap:9px;padding:10px 15px;border:1px solid rgba(191,219,254,.4);border-radius:999px;background:rgba(255,255,255,.1);color:#dbeafe;font-size:14px;font-weight:700}.dot{width:8px;height:8px;border-radius:50%;background:#5eead4}.hero h1{margin:24px 0 0;max-width:870px;font-size:clamp(38px,5.5vw,82px);line-height:1.04;letter-spacing:-.055em}.hero p{max-width:710px;margin:24px 0 0;color:#dbeafe;font-size:clamp(17px,1.5vw,21px);line-height:1.65}.hero-actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:36px}.hero-actions .button{font-size:15px}.button-light{color:#1e3a8a;background:#fff;border-color:#fff}.button-outline{color:#fff;border-color:rgba(255,255,255,.45);background:rgba(255,255,255,.06)}.features{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-top:38px}.feature{padding:25px;border:1px solid #e2e8f0;border-radius:20px;background:#fff;box-shadow:0 2px 6px rgba(15,23,42,.04)}.number{display:grid;width:40px;height:40px;place-items:center;border-radius:12px;color:#075985;background:#e0f2fe;font-size:12px;font-weight:800}.feature h2{margin:20px 0 0;font-size:18px}.feature p{margin:9px 0 0;color:#64748b;font-size:14px;line-height:1.65}@media(max-width:840px){.features{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.topbar{height:64px;padding:0 16px}.brand{font-size:16px}.brand-mark{width:36px;height:36px}.top-actions .login{display:none}main{width:min(100% - 24px,1500px);padding-top:24px}.hero{border-radius:22px}.features{grid-template-columns:1fr;gap:14px;margin-top:24px}.feature{padding:20px}}
    </style>
</head>
<body>
<header class="topbar"><a href="{{ route('home') }}" class="brand"><span class="brand-mark" aria-hidden="true">▣</span><span>Aprende Guate</span></a><nav class="top-actions" aria-label="Acciones de cuenta">@auth <a class="button" href="{{ route('adaptive.dashboard') }}">Ir a mi panel</a> @else <a class="login" href="{{ route('login') }}">Iniciar sesión</a>@if (Route::has('register'))<a class="button button-primary" href="{{ route('register') }}">Crear cuenta</a>@endif @endauth</nav></header>
<main>@yield('content')</main>
</body>
</html>